const modelAppearances={memorias:['cacau','cotton','paper','gentle'],historia:['azul','postal','sky','classic'],'album-casal':['perola','frame','studio','gentle'],natal:['noite','stars','cocoa','confetti'],maes:['amora','ribbon','rose','gentle'],pais:['azul','linen','sky','classic'],aniversario:['mel','confetti','paper','pop'],saudade:['lavanda','cotton','violet','float'],'convite-casamento':['perola','frame','studio','gentle'],'convite-festa':['coral','confetti','rose','spin'],formatura:['noite','postal','cocoa','classic'],pascoa:['terracota','dots','paper','gentle']};
models.forEach(model=>{const [palette,background,scene,animation]=modelAppearances[model.id];const art=occasionDirection(model);model.appearance={palette,background:art.background,scene,animation,custom:true,paper:art.paper,ink:art.ink,accent:art.accent,themeStyle:art.border%20,coverSurface:'paper'};model.bookFinish={material:art.material};});
export function renderCollection(onSelect,onPreview){
 const section=document.createElement('section');section.className='collection section-width';section.id='colecao';section.setAttribute('aria-labelledby','collection-title');
 section.innerHTML='<div class="section-heading"><div><p class="small-note">Encontre o seu começo</p><h2 id="collection-title">Uma coleção<br>para fazer sua.</h2></div><p>Livros, cartões e convites.<br>Suas fotos, suas palavras e um toque Capimimo.</p></div><div class="collection-tabs" aria-label="Filtrar modelos"><button data-filter="all" aria-pressed="true">Todos os modelos</button><button data-filter="livro" aria-pressed="false">Livros</button><button data-filter="cartao" aria-pressed="false">Cartões</button><button data-filter="convite" aria-pressed="false">Convites</button></div><div class="collection-grid"></div>';
 const exampleLabel=document.createElement('p');exampleLabel.className='fiction-note';exampleLabel.textContent='Modelos ilustrativos com pessoas fictícias. Personalize com as suas próprias fotos.';section.append(exampleLabel);const grid=section.querySelector('.collection-grid');grid.tabIndex=0;grid.setAttribute('aria-label','Modelos de presentes em 3D');const swipe=document.createElement('p');swipe.className='collection-swipe-hint';swipe.textContent='Deslize para explorar os modelos.';grid.before(swipe);
 for(const model of models){const card=document.createElement('article');card.className='collection-item';card.dataset.modelCard=model.id;card.dataset.kind=model.format;card.style.setProperty('--model-color',model.color);const art=document.createElement('span');art.className='collection-art';const preview=document.createElement('img');preview.className='model-preview';preview.src='assets/models/'+model.id+'.webp';preview.alt='Visualização em 3D do modelo '+model.title;preview.loading='lazy';preview.decoding='async';preview.width=420;preview.height=460;art.dataset.format=model.format;art.append(preview);const text=document.createElement('div');text.className='collection-info';const title=document.createElement('strong');title.textContent=model.title;const desc=document.createElement('span');desc.textContent=model.description;const actions=document.createElement('div');actions.className='collection-model-actions';const customize=document.createElement('button');customize.type='button';customize.className='collection-customize';customize.dataset.model=model.id;customize.setAttribute('aria-pressed','false');customize.textContent='Personalizar ↗';customize.addEventListener('click',()=>onSelect(model));const live=document.createElement('button');live.type='button';live.className='collection-view-3d';live.setAttribute('aria-label','Ver '+model.title+' em 3D');live.textContent='Ver em 3D';live.addEventListener('click',()=>onPreview?.(model));actions.append(customize,live);text.append(title,desc,actions);card.append(art,text);grid.append(card);}
 section.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{section.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));grid.querySelectorAll('[data-model-card]').forEach(x=>x.hidden=b.dataset.filter!=='all'&&x.dataset.kind!==b.dataset.filter);}));
 document.getElementById('atelier').before(section);
}
